// ── Tipos de worker (`L7`, `chunk-aywxqprf.js:14463-14602`) ────────────────

export type DaemonWorkerKind = 'heartbeat' | 'scheduled' | 'remoteControl'

/** Los tres tipos que `L7` declara, en su mismo orden. */
