export interface DaemonConfigReloadPlan {
  stop: Array<{ id: string; kind: DaemonWorkerKind; previousConfig: DaemonWorkerEntryConfig }>
  start: Array<{ id: string; kind: DaemonWorkerKind; config: DaemonWorkerEntryConfig }>
  restart: Array<{
